function requireBuildResourceGuard(value) {
  if (
    value?.kind !== convexWasmBuildResourceGuardKind ||
    value.released !== false ||
    typeof value.runCommand !== "function" ||
    typeof value.describeTermination !== "function"
  ) {
    fail("build resource guard must be an active caller-owned guard");
  }
  normalizeConvexWasmNativeLaunchPolicy(value.launchPolicy);
  return value;
}
