export function createBoundedRetainedAuthenticatedPayloadCache({
  description,
  maximumBytes,
  maximumEntries,
}) {
  const entries = new Map();
  let bytes = 0;
  let hitCount = 0;
  let missCount = 0;
  // The physical reader authenticates all four fields before this lookup. Keep each one in the
  // retained key so a copied payload at another immutable key, or a same-digest entry with
  // inconsistent size metadata, takes the complete caller validation path.
  const keyFor = (cacheRoot, entry) =>
    `${cacheRoot}\0${entry.key}\0${entry.artifactSha256}\0${String(entry.artifactSize)}`;
  return Object.freeze({
    get(cacheRoot, entry) {
      const key = keyFor(cacheRoot, entry);
      const retained = entries.get(key);
      if (retained === undefined) {
        missCount += 1;
        return undefined;
      }
      if (
        retained.artifactSha256 !== entry.artifactSha256 ||
        retained.artifactSize !== entry.artifactSize
      ) {
        fail(`${description} key has inconsistent payload metadata`);
      }
      entries.delete(key);
      entries.set(key, retained);
      hitCount += 1;
      return retained.value;
    },
    retain(cacheRoot, entry, value) {
      const key = keyFor(cacheRoot, entry);
      const existing = entries.get(key);
      if (existing !== undefined) {
        if (
          existing.artifactSha256 !== entry.artifactSha256 ||
          existing.artifactSize !== entry.artifactSize
        ) {
          fail(`${description} key has inconsistent payload metadata`);
        }
        entries.delete(key);
        entries.set(key, existing);
        return existing.value;
      }
      if (entry.artifactSize > maximumBytes) return value;
      while (
        entries.size >= maximumEntries ||
        (entries.size > 0 && bytes + entry.artifactSize > maximumBytes)
      ) {
        const oldestKey = entries.keys().next().value;
        const oldest = entries.get(oldestKey);
        entries.delete(oldestKey);
        bytes -= oldest.artifactSize;
      }
      entries.set(
        key,
        Object.freeze({
          artifactSha256: entry.artifactSha256,
          artifactSize: entry.artifactSize,
          value,
        })
      );
      bytes += entry.artifactSize;
      return value;
    },
    stats: () => ({ bytes, entries: entries.size, hits: hitCount, misses: missCount }),
  });
}

