      const modules = moduleInputs.modules.map((module, moduleIndex) =>
        normalizeModuleGraphModule(
          module,
          moduleRoles[moduleIndex],
          moduleRoles,
          engine.compatibilitySha256
        )
      );
      const leafInvalidation = createModuleGraphLeafInvalidation(modules, moduleInputs.routing);
