            const baseArtifacts = settlement.value;
            const prelink = baseArtifacts.basePrelink;
            const [authenticatedPrelinkSettlement] = await Promise.allSettled([
              validateArtifactCacheEntryFresh(
                cacheRoot,
                cacheLayout,
                prelink.report.stage,
                prelink.report.cacheKey,
                "wasm",
                Math.min(compilerOutput.options.limits.artifacts.wasmBytes, MAX_CORE_WASM_BYTES)
              ),
            ]);
            // This is speculative readiness only. The authoritative base path below repeats a
            // failed check and retains the established failure and fallback ordering.
            if (authenticatedPrelinkSettlement.status === "rejected") {
              return undefined;
            }
            const authenticatedPrelink = authenticatedPrelinkSettlement.value;
            if (
              authenticatedPrelink === undefined ||
              !moduleGraphCompilerOutputCacheEntryMatchesAuthority(
                authenticatedPrelink,
                prelink.entry
              ) ||
              currentModuleGraphBaseArtifactsPreactivation(compilerOutput) !==
                constructionBaseArtifactsPreactivation
            ) {
              return undefined;
            }
            const baseModuleDescription = describeBaseModule(baseArtifacts);
            const [aotMaterialPreactivationStart] = await Promise.allSettled([
              ...(constructionBaseArtifactsPreactivation.state
                .aotMaterialPreactivationStartPromise === undefined
                ? []
                : [
                    constructionBaseArtifactsPreactivation.state
                      .aotMaterialPreactivationStartPromise,
                  ]),
            ]);
            const aotMaterialPreactivation =
              aotMaterialPreactivationStart?.status === "fulfilled" &&
              aotMaterialPreactivationStart.value.baseArtifacts === baseArtifacts
                ? aotMaterialPreactivationStart.value.token
                : undefined;
